MODULE_SOURCE='\nfrom __future__ import annotations\nfrom dataclasses import dataclass\nfrom types import MappingProxyType\nfrom typing import Any, Iterable, Mapping, Tuple\n\nfrom .universal_market_discovery_foundation import UMD_SUBSYSTEM_ID, ImmutableLineage, deterministic_sha256\nfrom .umd_095_market_identity import CanonicalMarketIdentity\nfrom .umd_096_duplicate_resolution import DuplicateGroup\nfrom .umd_097_market_relationship_graph import MarketRelationshipGraph\nfrom .umd_098_market_taxonomy import MarketTaxonomyClassification\nfrom .umd_099_market_alias_resolution import AliasIndex\nfrom .umd_100_market_lifecycle import MarketLifecycle\nfrom .umd_101_outcome_schema import OutcomeSchema, verify_umd_101_outcome_schema_resolution\n\nUMD_102_BUILD_ID="UMD-102"\nUMD_102_BUILD_NAME="Canonical Market Record Assembly"\nUMD_102_REVISION="UMD_102_CANONICAL_MARKET_RECORD_ASSEMBLY_V1"\nUMD_102_SCHEMA_VERSION="1.0.0"\nPROHIBITED_CAPABILITIES=("network_invocation","persistence","mutation","publication","execution")\n\n\ndef _freeze(value:Mapping[str,Any] | None)->Mapping[str,Any]:\n    if value is None: value={}\n    if not isinstance(value,Mapping): raise TypeError("metadata must be a mapping")\n    return MappingProxyType(dict(sorted((str(k),v) for k,v in value.items())))\n\n\n@dataclass(frozen=True,slots=True)\nclass VenueMarketBinding:\n    venue_key:str\n    venue_market_id:str\n    identity_hash:str\n    def __post_init__(self):\n        if not self.venue_key or not self.venue_market_id: raise ValueError("venue binding fields must be non-empty")\n        if not isinstance(self.identity_hash,str) or len(self.identity_hash)!=64: raise ValueError("identity_hash must be SHA-256 hex")\n    def to_canonical_dict(self): return {"venue_key":self.venue_key,"venue_market_id":self.venue_market_id,"identity_hash":self.identity_hash}\n    @property\n    def binding_hash(self): return deterministic_sha256(self.to_canonical_dict())\n\n\n@dataclass(frozen=True,slots=True)\nclass CanonicalMarketRecord:\n    canonical_market_id:str\n    primary_identity_hash:str\n    venue_bindings:Tuple[VenueMarketBinding,...]\n    taxonomy_key:str\n    lifecycle_hash:str\n    outcome_schema_hash:str\n    alias_keys:Tuple[str,...]\n    relationship_hashes:Tuple[str,...]\n    duplicate_group_hash:str\n    metadata:Mapping[str,Any]\n    lineage:ImmutableLineage\n\n    def __post_init__(self):\n        object.__setattr__(self,"venue_bindings",tuple(self.venue_bindings)); object.__setattr__(self,"alias_keys",tuple(self.alias_keys)); object.__setattr__(self,"relationship_hashes",tuple(self.relationship_hashes)); object.__setattr__(self,"metadata",_freeze(self.metadata))\n        if not self.venue_bindings: raise ValueError("canonical record requires at least one venue binding")\n        if self.primary_identity_hash!=min(x.identity_hash for x in self.venue_bindings): raise ValueError("primary identity must be deterministic minimum hash")\n        if tuple(sorted(set(self.alias_keys)))!=self.alias_keys: raise ValueError("alias_keys must be sorted and unique")\n        if tuple(sorted(set(self.relationship_hashes)))!=self.relationship_hashes: raise ValueError("relationship_hashes must be sorted and unique")\n        if self.lineage.subsystem_id!=UMD_SUBSYSTEM_ID or self.lineage.build_id!=UMD_102_BUILD_ID: raise ValueError("lineage must belong to UMD-102")\n\n    def to_canonical_dict(self):\n        return {"canonical_market_id":self.canonical_market_id,"primary_identity_hash":self.primary_identity_hash,\n                "venue_binding_hashes":tuple(x.binding_hash for x in self.venue_bindings),"taxonomy_key":self.taxonomy_key,\n                "lifecycle_hash":self.lifecycle_hash,"outcome_schema_hash":self.outcome_schema_hash,"alias_keys":self.alias_keys,\n                "relationship_hashes":self.relationship_hashes,"duplicate_group_hash":self.duplicate_group_hash,"metadata":self.metadata,"lineage":self.lineage}\n    @property\n    def record_hash(self): return deterministic_sha256(self.to_canonical_dict())\n\n\nclass CanonicalMarketRecordAssembler:\n    __slots__=()\n    def assemble(self,identities:Iterable[CanonicalMarketIdentity],*,classification:MarketTaxonomyClassification,lifecycle:MarketLifecycle,\n                 outcome_schema:OutcomeSchema,alias_index:AliasIndex,relationship_graph:MarketRelationshipGraph,lineage:ImmutableLineage,\n                 duplicate_group:DuplicateGroup | None=None,metadata:Mapping[str,Any] | None=None)->CanonicalMarketRecord:\n        values=tuple(identities)\n        if not values or any(not isinstance(x,CanonicalMarketIdentity) for x in values): raise TypeError("identities must contain CanonicalMarketIdentity")\n        canonical_ids={x.canonical_market_id for x in values}\n        if len(canonical_ids)!=1: raise ValueError("all identities must represent the same canonical market")\n        canonical_id=next(iter(canonical_ids)); ordered=tuple(sorted(values,key=lambda x:(x.identity_hash,x.venue_key,x.venue_market_id)))\n        if len({x.identity_hash for x in ordered})!=len(ordered): raise ValueError("identity hashes must be unique")\n        primary=ordered[0]\n        if classification.canonical_market_id!=canonical_id or classification.identity_hash!=primary.identity_hash: raise ValueError("classification must belong to primary identity")\n        if lifecycle.canonical_market_id!=canonical_id or lifecycle.identity_hash!=primary.identity_hash: raise ValueError("lifecycle must belong to primary identity")\n        if outcome_schema.canonical_market_id!=canonical_id or outcome_schema.identity_hash!=primary.identity_hash: raise ValueError("outcome schema must belong to primary identity")\n        if canonical_id not in relationship_graph.market_ids: raise ValueError("relationship graph must contain canonical market")\n        venues={x.venue_key for x in ordered}\n        if len(venues)>1:\n            if duplicate_group is None: raise ValueError("cross-venue record requires duplicate group")\n            if duplicate_group.canonical_market_id!=canonical_id or set(duplicate_group.member_identity_hashes)!={x.identity_hash for x in ordered}: raise ValueError("duplicate group does not match identities")\n            if duplicate_group.primary_identity_hash!=primary.identity_hash: raise ValueError("duplicate group primary identity mismatch")\n        elif duplicate_group is not None: raise ValueError("duplicate group is invalid for single-venue record")\n        alias_keys=tuple(sorted({b.alias_key for b in alias_index.bindings if b.canonical_market_id==canonical_id}))\n        relation_hashes=tuple(sorted({r.relationship_hash for r in relationship_graph.related_to(canonical_id)}))\n        required={x.identity_hash for x in ordered}\n        required.update((classification.classification_hash,lifecycle.lifecycle_hash,outcome_schema.outcome_schema_hash,alias_index.index_hash,relationship_graph.graph_hash))\n        if duplicate_group is not None: required.add(duplicate_group.group_hash)\n        if not required.issubset(set(lineage.parent_hashes)): raise ValueError("lineage must include all assembled artifact hashes")\n        bindings=tuple(VenueMarketBinding(x.venue_key,x.venue_market_id,x.identity_hash) for x in ordered)\n        return CanonicalMarketRecord(canonical_market_id=canonical_id,primary_identity_hash=primary.identity_hash,venue_bindings=bindings,\n            taxonomy_key=classification.taxonomy_path.taxonomy_key,lifecycle_hash=lifecycle.lifecycle_hash,outcome_schema_hash=outcome_schema.outcome_schema_hash,\n            alias_keys=alias_keys,relationship_hashes=relation_hashes,duplicate_group_hash="" if duplicate_group is None else duplicate_group.group_hash,\n            metadata={} if metadata is None else metadata,lineage=lineage)\n\n\ndef build_umd_102_certification_manifest():\n    data={"subsystem_id":"UMD","build_id":UMD_102_BUILD_ID,"revision":UMD_102_REVISION,"schema_version":UMD_102_SCHEMA_VERSION,\n          "upstream_builds":("UMD-095","UMD-096","UMD-097","UMD-098","UMD-099","UMD-100","UMD-101"),\n          "mode":"deterministic_read_only_canonical_market_record_assembly","prohibited_capabilities":PROHIBITED_CAPABILITIES,\n          "network_enabled":False,"persistence_enabled":False,"mutation_enabled":False,"publication_enabled":False,"execution_enabled":False}\n    return MappingProxyType({**data,"manifest_hash":deterministic_sha256(data)})\n\n\ndef verify_umd_102_canonical_market_record_assembly()->bool:\n    if verify_umd_101_outcome_schema_resolution() is not True: return False\n    m=build_umd_102_certification_manifest()\n    return m["build_id"]=="UMD-102" and not any(m[k] for k in ("network_enabled","persistence_enabled","mutation_enabled","publication_enabled","execution_enabled"))\n'
TEST_SOURCE='\nfrom __future__ import annotations\nimport unittest\nfrom dataclasses import FrozenInstanceError\nfrom datetime import datetime,timezone\n\nfrom qseries_v2.universal_market_discovery.universal_market_discovery_foundation import ImmutableLineage\nfrom qseries_v2.universal_market_discovery.umd_094_market_normalization import UMD_094_REVISION,MarketObservation,MarketNormalizer\nfrom qseries_v2.universal_market_discovery.umd_095_market_identity import UMD_095_REVISION,CanonicalMarketIdentityResolver\nfrom qseries_v2.universal_market_discovery.umd_096_duplicate_resolution import UMD_096_REVISION,CrossVenueDuplicateResolver\nfrom qseries_v2.universal_market_discovery.umd_097_market_relationship_graph import UMD_097_REVISION,MarketRelationshipGraphBuilder\nfrom qseries_v2.universal_market_discovery.umd_098_market_taxonomy import UMD_098_REVISION,TaxonomyPath,TaxonomyRule,MarketTaxonomyClassifier\nfrom qseries_v2.universal_market_discovery.umd_099_market_alias_resolution import UMD_099_REVISION,MarketAliasResolver\nfrom qseries_v2.universal_market_discovery.umd_100_market_lifecycle import UMD_100_REVISION,MarketLifecycleResolver\nfrom qseries_v2.universal_market_discovery.umd_101_outcome_schema import UMD_101_REVISION,OutcomeSchemaResolver\nfrom qseries_v2.universal_market_discovery.umd_102_canonical_market_record import (\n    UMD_102_REVISION,CanonicalMarketRecordAssembler,build_umd_102_certification_manifest,verify_umd_102_canonical_market_record_assembly,\n)\n\nFIXED=datetime(2026,8,9,12,20,tzinfo=timezone.utc)\n\ndef identity(venue,mid):\n    o=MarketObservation(venue=venue,venue_market_id=mid,title="Will BTC exceed 100K?",category="Crypto",status="Open",close_time="2026-08-10T00:00:00Z",settlement_time="2026-08-11T00:00:00Z",outcomes=("Yes","No"))\n    l94=ImmutableLineage(subsystem_id="UMD",build_id="UMD-094",revision=UMD_094_REVISION,schema_version="1.0.0",parent_hashes=(o.observation_hash,),source_refs=("fixture://102/94",),created_at=FIXED)\n    m=MarketNormalizer().normalize(o,lineage=l94)\n    l95=ImmutableLineage(subsystem_id="UMD",build_id="UMD-095",revision=UMD_095_REVISION,schema_version="1.0.0",parent_hashes=(m.normalized_market_hash,),source_refs=("fixture://102/95",),created_at=FIXED)\n    return CanonicalMarketIdentityResolver().resolve(m,lineage=l95)\n\ndef artifacts(ids):\n    primary=min(ids,key=lambda x:x.identity_hash)\n    l98=ImmutableLineage(subsystem_id="UMD",build_id="UMD-098",revision=UMD_098_REVISION,schema_version="1.0.0",parent_hashes=(primary.identity_hash,),source_refs=("fixture://102/98",),created_at=FIXED)\n    classification=MarketTaxonomyClassifier((TaxonomyRule("crypto",TaxonomyPath("btc","digital-assets","crypto","bitcoin","price-threshold"),category_keys=("crypto",),priority=1),)).classify(primary,lineage=l98)\n    l100=ImmutableLineage(subsystem_id="UMD",build_id="UMD-100",revision=UMD_100_REVISION,schema_version="1.0.0",parent_hashes=(primary.identity_hash,),source_refs=("fixture://102/100",),created_at=FIXED)\n    lifecycle=MarketLifecycleResolver().resolve(primary,as_of=FIXED,lineage=l100)\n    l101=ImmutableLineage(subsystem_id="UMD",build_id="UMD-101",revision=UMD_101_REVISION,schema_version="1.0.0",parent_hashes=(primary.identity_hash,),source_refs=("fixture://102/101",),created_at=FIXED)\n    outcome=OutcomeSchemaResolver().resolve(primary,lineage=l101)\n    l99=ImmutableLineage(subsystem_id="UMD",build_id="UMD-099",revision=UMD_099_REVISION,schema_version="1.0.0",parent_hashes=tuple(x.identity_hash for x in ids),source_refs=("fixture://102/99",),created_at=FIXED)\n    entries=tuple((x,classification if x is primary else classification,("BTC above 100K",),f"fixture://alias/{n}") for n,x in enumerate(ids))\n    # Alias resolver requires classification identity to match each identity, so only bind aliases to primary here.\n    alias_index=MarketAliasResolver().build_index(((primary,classification,("BTC above 100K","BTC 100K"),"fixture://alias/primary"),),lineage=ImmutableLineage(subsystem_id="UMD",build_id="UMD-099",revision=UMD_099_REVISION,schema_version="1.0.0",parent_hashes=(primary.identity_hash,),source_refs=("fixture://102/99",),created_at=FIXED))\n    l97=ImmutableLineage(subsystem_id="UMD",build_id="UMD-097",revision=UMD_097_REVISION,schema_version="1.0.0",parent_hashes=tuple(x.identity_hash for x in ids),source_refs=("fixture://102/97",),created_at=FIXED)\n    graph=MarketRelationshipGraphBuilder().build(ids,(),lineage=l97)\n    dup=None\n    if len({x.venue_key for x in ids})>1:\n        l96=ImmutableLineage(subsystem_id="UMD",build_id="UMD-096",revision=UMD_096_REVISION,schema_version="1.0.0",parent_hashes=tuple(x.identity_hash for x in ids),source_refs=("fixture://102/96",),created_at=FIXED)\n        dup=CrossVenueDuplicateResolver().resolve(ids,lineage=l96)[0]\n    return primary,classification,lifecycle,outcome,alias_index,graph,dup\n\ndef record_lineage(ids,classification,lifecycle,outcome,alias_index,graph,dup):\n    parents=[x.identity_hash for x in ids]+[classification.classification_hash,lifecycle.lifecycle_hash,outcome.outcome_schema_hash,alias_index.index_hash,graph.graph_hash]\n    if dup is not None: parents.append(dup.group_hash)\n    return ImmutableLineage(subsystem_id="UMD",build_id="UMD-102",revision=UMD_102_REVISION,schema_version="1.0.0",parent_hashes=tuple(parents),source_refs=("fixture://102",),created_at=FIXED)\n\nclass TestUMD102(unittest.TestCase):\n    def test_foundation(self): self.assertTrue(verify_umd_102_canonical_market_record_assembly())\n    def test_single_venue_record(self):\n        ids=(identity("Kalshi","A"),); _,c,l,o,a,g,d=artifacts(ids); r=CanonicalMarketRecordAssembler().assemble(ids,classification=c,lifecycle=l,outcome_schema=o,alias_index=a,relationship_graph=g,duplicate_group=d,lineage=record_lineage(ids,c,l,o,a,g,d)); self.assertEqual(len(r.venue_bindings),1); self.assertEqual(r.duplicate_group_hash,"")\n    def test_cross_venue_record(self):\n        ids=(identity("Kalshi","A"),identity("Polymarket","B")); _,c,l,o,a,g,d=artifacts(ids); r=CanonicalMarketRecordAssembler().assemble(ids,classification=c,lifecycle=l,outcome_schema=o,alias_index=a,relationship_graph=g,duplicate_group=d,lineage=record_lineage(ids,c,l,o,a,g,d)); self.assertEqual(len(r.venue_bindings),2); self.assertTrue(r.duplicate_group_hash)\n    def test_cross_venue_requires_duplicate_group(self):\n        ids=(identity("Kalshi","A"),identity("Polymarket","B")); _,c,l,o,a,g,d=artifacts(ids)\n        with self.assertRaises(ValueError): CanonicalMarketRecordAssembler().assemble(ids,classification=c,lifecycle=l,outcome_schema=o,alias_index=a,relationship_graph=g,duplicate_group=None,lineage=record_lineage(ids,c,l,o,a,g,d))\n    def test_different_market_rejected(self):\n        a=identity("Kalshi","A")\n        o=MarketObservation(venue="Kalshi",venue_market_id="B",title="Will BTC exceed 200K?",category="Crypto",status="Open",outcomes=("Yes","No"))\n        l94=ImmutableLineage(subsystem_id="UMD",build_id="UMD-094",revision=UMD_094_REVISION,schema_version="1.0.0",parent_hashes=(o.observation_hash,),source_refs=("fixture://102/diff94",),created_at=FIXED); m=MarketNormalizer().normalize(o,lineage=l94)\n        l95=ImmutableLineage(subsystem_id="UMD",build_id="UMD-095",revision=UMD_095_REVISION,schema_version="1.0.0",parent_hashes=(m.normalized_market_hash,),source_refs=("fixture://102/diff95",),created_at=FIXED); b=CanonicalMarketIdentityResolver().resolve(m,lineage=l95)\n        _,c,l,out,ai,g,d=artifacts((a,))\n        with self.assertRaises(ValueError): CanonicalMarketRecordAssembler().assemble((a,b),classification=c,lifecycle=l,outcome_schema=out,alias_index=ai,relationship_graph=g,lineage=record_lineage((a,),c,l,out,ai,g,d))\n    def test_aliases_canonical(self):\n        ids=(identity("Kalshi","A"),); _,c,l,o,a,g,d=artifacts(ids); r=CanonicalMarketRecordAssembler().assemble(ids,classification=c,lifecycle=l,outcome_schema=o,alias_index=a,relationship_graph=g,lineage=record_lineage(ids,c,l,o,a,g,d)); self.assertEqual(r.alias_keys,("btc-100k","btc-above-100k"))\n    def test_primary_deterministic(self):\n        ids=(identity("Kalshi","A"),identity("Polymarket","B")); _,c,l,o,a,g,d=artifacts(ids); r=CanonicalMarketRecordAssembler().assemble(tuple(reversed(ids)),classification=c,lifecycle=l,outcome_schema=o,alias_index=a,relationship_graph=g,duplicate_group=d,lineage=record_lineage(ids,c,l,o,a,g,d)); self.assertEqual(r.primary_identity_hash,min(x.identity_hash for x in ids))\n    def test_lineage_required(self):\n        ids=(identity("Kalshi","A"),); _,c,l,o,a,g,d=artifacts(ids); bad=ImmutableLineage(subsystem_id="UMD",build_id="UMD-102",revision=UMD_102_REVISION,schema_version="1.0.0",parent_hashes=("0"*64,),source_refs=("bad",),created_at=FIXED)\n        with self.assertRaises(ValueError): CanonicalMarketRecordAssembler().assemble(ids,classification=c,lifecycle=l,outcome_schema=o,alias_index=a,relationship_graph=g,lineage=bad)\n    def test_immutable(self):\n        ids=(identity("Kalshi","A"),); _,c,l,o,a,g,d=artifacts(ids); r=CanonicalMarketRecordAssembler().assemble(ids,classification=c,lifecycle=l,outcome_schema=o,alias_index=a,relationship_graph=g,lineage=record_lineage(ids,c,l,o,a,g,d))\n        with self.assertRaises((FrozenInstanceError,AttributeError)): r.alias_keys=()\n    def test_deterministic(self):\n        ids=(identity("Kalshi","A"),); _,c,l,o,a,g,d=artifacts(ids); ln=record_lineage(ids,c,l,o,a,g,d); x=CanonicalMarketRecordAssembler(); self.assertEqual(x.assemble(ids,classification=c,lifecycle=l,outcome_schema=o,alias_index=a,relationship_graph=g,lineage=ln).record_hash,x.assemble(ids,classification=c,lifecycle=l,outcome_schema=o,alias_index=a,relationship_graph=g,lineage=ln).record_hash)\n    def test_side_effects(self):\n        m=build_umd_102_certification_manifest(); self.assertFalse(any(m[k] for k in ("network_enabled","persistence_enabled","mutation_enabled","publication_enabled","execution_enabled")))\n\nif __name__=="__main__":\n    print("="*72); print(" UMD-102 CERTIFICATION TEST"); print(" CANONICAL MARKET RECORD ASSEMBLY"); print("="*72)\n    r=unittest.TextTestRunner(verbosity=2).run(unittest.defaultTestLoader.loadTestsFromTestCase(TestUMD102))\n    if not r.wasSuccessful(): raise SystemExit(1)\n    m=build_umd_102_certification_manifest(); print(); print(f"[PASS] Build: {m[\'build_id\']}"); print(f"[PASS] Revision: {m[\'revision\']}"); print(f"[PASS] Manifest hash: {m[\'manifest_hash\']}")\n    print("[PASS] UMD-095 through UMD-101 capability artifacts assembled read-only"); print("[PASS] Deterministic canonical market record assembly certified")\n    print("[PASS] Network, persistence, publication, and execution disabled"); print("[DONE] UMD-102 CERTIFIED")\n'
UPSTREAM_MODULE='umd_101_outcome_schema'
UPSTREAM_VERIFIER='verify_umd_101_outcome_schema_resolution'
EXPORTED_NAMES=('UMD_102_REVISION', 'VenueMarketBinding', 'CanonicalMarketRecord', 'CanonicalMarketRecordAssembler', 'build_umd_102_certification_manifest', 'verify_umd_102_canonical_market_record_assembly')

def verify_upstream():
    sys.path.insert(0,str(ROOT))
    try:
        mod=importlib.import_module("qseries_v2.universal_market_discovery."+UPSTREAM_MODULE)
        verifier=getattr(mod,UPSTREAM_VERIFIER,None)
        if verifier is None:
            raise RuntimeError(f"Certified upstream verifier missing: {UPSTREAM_MODULE}.{UPSTREAM_VERIFIER}")
        if verifier() is not True:
            raise RuntimeError(f"Certified upstream verification failed: {UPSTREAM_MODULE}")
    finally:
        if str(ROOT) in sys.path: sys.path.remove(str(ROOT))

def write_exact(path,source):
    path.parent.mkdir(parents=True,exist_ok=True)
    tmp=path.with_suffix(path.suffix+".tmp")
    tmp.write_text(source.lstrip("\n"),encoding="utf-8",newline="\n")
    os.replace(tmp,path)

def update_init():
    current=INIT.read_text(encoding="utf-8") if INIT.exists() else ""
    marker=f"# UMD-102 exports"
    block=marker+"\nfrom ."+MODULE.stem+" import (\n"+"".join(f"    {name},\n" for name in EXPORTED_NAMES)+")\n"
    if marker not in current:
        write_exact(INIT,current.rstrip()+"\n\n"+block)

def verify_current():
    sys.path.insert(0,str(ROOT))
    try:
        name="qseries_v2.universal_market_discovery."+MODULE.stem
        sys.modules.pop(name,None); importlib.invalidate_caches()
        mod=importlib.import_module(name)
        missing=[n for n in EXPORTED_NAMES if not hasattr(mod,n)]
        if missing: raise RuntimeError("UMD-102 missing symbols: "+", ".join(missing))
        verifier_name=[n for n in EXPORTED_NAMES if n.startswith("verify_")][0]
        if getattr(mod,verifier_name)() is not True: raise RuntimeError("UMD-102 verification returned false")
    finally:
        if str(ROOT) in sys.path: sys.path.remove(str(ROOT))

def sha256_file(path): return hashlib.sha256(path.read_bytes()).hexdigest()

def main():
    print("="*72); print(" UMD-102 INSTALLER"); print(" CANONICAL MARKET RECORD ASSEMBLY"); print("="*72)
    print(f"[BOOT] Revision: {REVISION}"); print(f"[ROOT] {ROOT}")
    verify_upstream(); print("[PASS] Certified upstream verified read-only")
    backups={p:(p.read_bytes() if p.exists() else None) for p in (MODULE,INIT,TEST)}
    try:
        write_exact(MODULE,MODULE_SOURCE); write_exact(TEST,TEST_SOURCE); update_init()
        compile(MODULE.read_text(encoding="utf-8"),str(MODULE),"exec")
        compile(INIT.read_text(encoding="utf-8"),str(INIT),"exec")
        compile(TEST.read_text(encoding="utf-8"),str(TEST),"exec")
        verify_current()
    except Exception:
        for p,previous in backups.items():
            if previous is None:
                if p.exists(): p.unlink()
            else: p.write_bytes(previous)
        importlib.invalidate_caches(); print("[ROLLBACK] UMD-102 installation failed; all affected files restored"); raise
    manifest={"build_id":'UMD-102',"revision":REVISION,"production_module":MODULE.name,"test":TEST.name,
        "files":{str(MODULE.relative_to(ROOT)):sha256_file(MODULE),str(INIT.relative_to(ROOT)):sha256_file(INIT),str(TEST.relative_to(ROOT)):sha256_file(TEST)},
        "network_enabled":False,"persistence_enabled":False,"publication_enabled":False,"execution_enabled":False}
    h=hashlib.sha256(json.dumps(manifest,sort_keys=True,separators=(",",":")).encode()).hexdigest()
    print(f"[PASS] Wrote: {MODULE.relative_to(ROOT)}"); print(f"[PASS] Updated: {INIT.relative_to(ROOT)}"); print(f"[PASS] Wrote: {TEST.relative_to(ROOT)}")
    print("[PASS] In-memory compilation verified"); print("[PASS] Required symbols and verifier certified")
    print(f"[PASS] Deterministic install hash: {h}")
    print("[PASS] Network, persistence, publication, and execution disabled"); print("[DONE] UMD-102 INSTALLATION COMPLETE"); return 0

if __name__=="__main__": raise SystemExit(main())
